#!/usr/bin/env bash
# Run inside the freshly built ROS workspace container.
set -eo pipefail
# Generated by colcon inside the build container.
# shellcheck disable=SC1091
source /workspace/ros2_ws/install/setup.bash
set -u

package_share=$(ros2 pkg prefix --share swarm_bringup)
upstream_share=$(ros2 pkg prefix --share turtlebot3_gazebo)
source_share=/workspace/ros2_ws/src/swarm_bringup

# Compare full trees so missing or stale installed resources fail the build.
diff "$source_share/package.xml" "$package_share/package.xml"
for directory in launch config worlds; do
    diff -r "$source_share/$directory" "$package_share/$directory"
done
for model in turtlebot3_burger turtlebot3_common; do
    diff -r "$upstream_share/models/$model" "$package_share/simulation/$model"
done
echo "Verified swarm_bringup installation and TurtleBot3 assets."
